css:
:root { --p05c-col: 52rem; --p05c-area-min: clamp(8rem, 38cqh, 18rem); --p05c-room: 2rem; --p05c-combo-room: 3.25rem; --p05c-tab-end: 1.5rem; --p05c-menu-min: 10rem; --p05c-menu-rest: 7rem; }
.p05c-wrap { max-width: var(--p05c-col); margin-inline: auto; display: grid; gap: var(--s-3); margin-top: calc(var(--p05c-scroll, 0rem) * -1); }
.p05c-top { display: grid; gap: var(--s-2); }
.p05c-form { display: grid; gap: var(--s-4); }
.p05c-form .field__head { display: flex; flex-wrap: wrap; align-items: baseline; justify-content: flex-start; column-gap: var(--s-2); }
.p05c-pos { position: relative; }
.p05c-ph { color: var(--muted); }
.p05c-form .select[aria-invalid="true"] { border-color: var(--terra); outline: var(--w1) solid var(--terra); outline-offset: calc(var(--w1) * -2); }
.p05c-form .select.p05c-focus { border-color: var(--blue); outline: var(--w1) solid var(--blue); outline-offset: calc(var(--w1) * -2); }
.p05c-combo { position: relative; }
.p05c-combo .textarea { padding-inline-end: var(--p05c-combo-room); }
.p05c-combo__btn { position: absolute; inset-block-start: 0; inset-inline-end: var(--w2); }
.p05c-name { min-height: var(--ctl-h); resize: none; field-sizing: content; }
.p05c-area { position: relative; }
.p05c-area .textarea { min-height: var(--p05c-area-min); resize: none; }
.field__count.is-over { color: var(--ink); font-weight: var(--fw-bold); }
.p05c-focus { border-color: var(--blue); outline: var(--w1) solid var(--blue); outline-offset: calc(var(--w1) * -2); }
.p05c-e { --frame-w: var(--w2); }
.p05c-ro { display: grid; }
.rec.p05c-roc { grid-template-columns: minmax(0, 1fr); grid-template-areas: "body"; padding-inline: 0; border-top: var(--w1) solid var(--rule); }
.p05c-actions { display: flex; flex-wrap: wrap; justify-content: center; gap: var(--s-2); }
.p05c-actions > .btn { flex: 1 1 0; }
.p05c-actions--3 { display: grid; gap: var(--s-3); }
.p05c-main { display: flex; gap: var(--s-2); }
.p05c-main > * { flex: 1 1 0; }
@media (min-width: 48rem) and (min-height: 31.25rem) {
  .p05c-actions > .btn { flex: none; }
  .p05c-actions--3 { grid-template-columns: 1fr auto 1fr; align-items: center; }
  .p05c-actions--3 > .p05c-del { justify-self: start; }
  .p05c-main > * { flex: none; }
}
.p05c-tipwrap { display: flex; justify-content: center; }
.p05c-actions .btn .spinner { width: var(--icon-sm); height: var(--icon-sm); }
.p05c-deleted { display: grid; justify-items: center; gap: var(--s-3); padding: var(--s-4) 0; }
.p05c-deleted .banner { width: 100%; justify-content: center; text-align: center; }
.p05c-app .tabwrap > .tab { padding-inline: var(--s-1) var(--p05c-tab-end); }
.p05c-app .tab__help { inset-inline-end: var(--w2); }
.dialog__foot.p05c-foot { flex-direction: column; }
.p05c-foot > * { flex: none; }
:root { --p05c-area-min: clamp(6rem, 28cqh, 12rem); }
.p05c-dtip { display: flex; justify-content: flex-end; padding: 0 var(--s-4) var(--s-4); margin-top: calc(var(--s-3) * -1 + var(--s-1)); }
.p05c-note { color: var(--muted); }
.p05c-word { display: grid; gap: var(--s-1); }
.p05c-dlg .dialog__foot .btn .spinner { width: var(--icon-sm); height: var(--icon-sm); }

.brand { min-height: var(--hit); }
.emo { width: 1.125em; height: 1.125em; flex: none; vertical-align: -0.2em; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }
@media (min-width: 37.5rem) and (max-height: 31.1875rem) { .tab { padding-inline: var(--s-1); } }
